import{_ as t,o as n,c as r,a6 as e}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"HTTP/1.1 协议详解","description":"逐字段拆解 HTTP/1.1——报文语法、起始行、方法、状态码与每一个头字段的精确语义。","frontmatter":{"title":"HTTP/1.1 协议详解","description":"逐字段拆解 HTTP/1.1——报文语法、起始行、方法、状态码与每一个头字段的精确语义。","source":"https://daiw.org/manual/http11"},"headers":[],"relativePath":"manual/computer-programming/http11/index.md","filePath":"manual/computer-programming/http11/index.md"}'),o={name:"manual/computer-programming/http11/index.md"};function p(s,a,l,u,m,i){return n(),r("div",null,[...a[0]||(a[0]=[e(`<h1 id="http-1-1-协议详解" tabindex="-1">HTTP/1.1 协议详解 <a class="header-anchor" href="#http-1-1-协议详解" aria-label="Permalink to &quot;HTTP/1.1 协议详解&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/http11" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David · 原文更新于 2026-08-03</p></blockquote><p>本专栏逐字段解析 HTTP/1.1：<strong>报文怎么切分、每个字段的 ABNF 语法是什么、取值范围有哪些、收到非法值该怎么办</strong>。不讲发展史，不讲「为什么要有网络」，只讲协议本身。</p><h2 id="规范基准" tabindex="-1">规范基准 <a class="header-anchor" href="#规范基准" aria-label="Permalink to &quot;规范基准&quot;">​</a></h2><p>以 <strong>RFC 9110（HTTP 语义）</strong> 与 <strong>RFC 9112（HTTP/1.1 报文语法）</strong> 为准，二者于 2022 年 6 月取代 RFC 7230–7235（更早的 RFC 2616 已废弃）。相关：RFC 9111（缓存）、RFC 6265（Cookie）、RFC 7617（Basic 认证）。</p><p>字段语义归 RFC 9110（跨版本通用），<strong>报文成帧与连接管理归 RFC 9112（HTTP/1.1 专属）</strong>——这是理解「哪些东西 HTTP/2 还有、哪些没了」的分界线。</p><h2 id="记号约定" tabindex="-1">记号约定 <a class="header-anchor" href="#记号约定" aria-label="Permalink to &quot;记号约定&quot;">​</a></h2><p>全书用 <strong>ABNF</strong>（RFC 5234）描述语法，并复用 RFC 9110 的核心规则：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OWS  = *( SP / HTAB )          ; optional whitespace</span></span>
<span class="line"><span>RWS  = 1*( SP / HTAB )         ; required whitespace</span></span>
<span class="line"><span>BWS  = OWS                     ; &quot;bad&quot; whitespace，语法允许但语义上应为空</span></span>
<span class="line"><span>tchar = &quot;!&quot; / &quot;#&quot; / &quot;$&quot; / &quot;%&quot; / &quot;&amp;&quot; / &quot;&#39;&quot; / &quot;*&quot; / &quot;+&quot; / &quot;-&quot; / &quot;.&quot; /</span></span>
<span class="line"><span>        &quot;^&quot; / &quot;_&quot; / &quot;\`&quot; / &quot;|&quot; / &quot;~&quot; / DIGIT / ALPHA</span></span>
<span class="line"><span>token = 1*tchar</span></span>
<span class="line"><span>quoted-string = DQUOTE *( qdtext / quoted-pair ) DQUOTE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>CRLF</code> 一律指 <code>\\r\\n</code>（0x0D 0x0A）。示例报文中的行尾均为 CRLF，正文里不再重复标注。</p><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><p><strong>第 1 部分 · 报文与成帧</strong>——<a href="/Front2Full/manual/computer-programming/http11/message-format">报文结构</a>、<a href="/Front2Full/manual/computer-programming/http11/request-line">请求行</a>、<a href="/Front2Full/manual/computer-programming/http11/status-line">状态行</a>、<a href="/Front2Full/manual/computer-programming/http11/field-syntax">字段行语法</a>、<a href="/Front2Full/manual/computer-programming/http11/message-body-length">消息体长度</a>、<a href="/Front2Full/manual/computer-programming/http11/connection-management">连接管理</a>。HTTP/1.1 的骨架，先读。</p><p><strong>第 2 部分 · 方法与状态码</strong>——<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>的安全性/幂等性/可缓存性，以及 <a href="/Front2Full/manual/computer-programming/http11/status-codes">1xx/2xx</a>、<a href="/Front2Full/manual/computer-programming/http11/status-3xx">3xx</a>、<a href="/Front2Full/manual/computer-programming/http11/status-4xx">4xx</a>、<a href="/Front2Full/manual/computer-programming/http11/status-5xx">5xx</a> 每个码的精确触发条件。</p><p><strong>第 3 部分 · 字段详解</strong>——<a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示字段</a>、<a href="/Front2Full/manual/computer-programming/http11/content-negotiation">内容协商</a>、<a href="/Front2Full/manual/computer-programming/http11/http-date">日期</a>、<a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件请求</a>、<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围请求</a>、<a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a>、<a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a>、<a href="/Front2Full/manual/computer-programming/http11/cookies">Cookie</a>、<a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文字段</a>、<a href="/Front2Full/manual/computer-programming/http11/proxy-fields">代理字段</a>，末尾附 <a href="/Front2Full/manual/computer-programming/http11/field-index">字段速查表</a>。</p><p>急用查字段直接跳 <a href="/Front2Full/manual/computer-programming/http11/field-index">字段速查表</a>；系统读从 <a href="/Front2Full/manual/computer-programming/http11/message-format">报文结构</a> 开始。</p>`,15)])])}const g=t(o,[["render",p]]);export{c as __pageData,g as default};
